def vincular(apps, schema_editor):
    """Une las tareas existentes con su cliente registrado (por proyecto, orden o nombre igual). Solo llena el campo nuevo."""
    Tarea = apps.get_model('desempeno', 'Tarea')
    Cliente = apps.get_model('operaciones', 'Cliente')
    por_nombre = {c.nombre.strip().lower(): c.id for c in Cliente.objects.all()}
    for t in Tarea._base_manager.filter(cliente_ref__isnull=True).select_related('proyecto', 'orden').iterator():
        cid = (t.proyecto.cliente_id if t.proyecto_id else None) or (t.orden.cliente_id if t.orden_id else None) \
            or por_nombre.get((t.cliente or '').strip().lower())
        if cid:
            Tarea._base_manager.filter(pk=t.pk).update(cliente_ref_id=cid)   # update(): no toca la fecha de modificación


